<script setup lang="ts">
import {computed,inject,onBeforeUnmount,ref,watch,type ComputedRef} from 'vue';
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRoute} from 'vue-router';
import {CheckCircle2,Layers3,LoaderCircle,Tag} from 'lucide-vue-next';
import type {BindSchemaLayersInput,ProjectSchemaState,PublishedTemplateSnapshot,RepositoryPermissions,SchemaLayer,TemplateTargetKind} from '@oxen/shared';
import {post,queryString,request} from '../api';
import {useAppStore} from '../stores/app';
const props=defineProps<{base:string;branch:string}>(),emit=defineEmits<{bound:[]}>(),app=useAppStore(),route=useRoute();
const permissions=inject<ComputedRef<RepositoryPermissions>>('repositoryPermissions'),canBind=computed(()=>!route.query.commit&&permissions?.value.capabilities?.['schema.bind']===true),canMaintain=computed(()=>permissions?.value.capabilities?.['schema.manage']===true);
interface Item {id:string;name:string;version:number;domain:string;domainName?:string;description:string;checksum:string;targetKind?:TemplateTargetKind}
const layers:SchemaLayer[]=['dataset','sample'],state=ref<ProjectSchemaState>(),projectState=ref<ProjectSchemaState>(),templates=ref<Item[]>([]),selected=ref<Record<SchemaLayer,string>>({dataset:'',sample:''}),baseline=ref(''),previews=ref<Partial<Record<SchemaLayer,PublishedTemplateSnapshot>>>({}),loading=ref(false),busy=ref(false),error=ref(''),domain=ref('');
let generation=0;const previewVersions:Record<SchemaLayer,number>={dataset:0,sample:0};
const layerName=(layer:SchemaLayer)=>layer==='dataset'?'项目标签模板':'样本标签模板';
const editableLayers=computed<SchemaLayer[]>(()=>props.branch==='main'?layers:['sample']);
const domainName=(value:string)=>templates.value.find(item=>item.domain===value)?.domainName??({general:'通用','ai-safety':'AI 安全'}[value]??value);
const domains=computed(()=>[...new Set(templates.value.filter(item=>item.targetKind!=='legacy').map(item=>item.domain))]);
const dirty=computed(()=>JSON.stringify(selected.value)!==baseline.value);
const currentLayer=(layer:SchemaLayer)=>{const current=layer==='dataset'?projectState.value:state.value;return current?.binding?.version===2?current.binding.layers[layer]:undefined;};
const choices=(layer:SchemaLayer)=>templates.value.filter(item=>item.targetKind===layer&&(!domain.value||item.domain===domain.value||key(item)===selected.value[layer])).sort((a,b)=>a.name.localeCompare(b.name)||b.version-a.version);
const chosenLayers=computed(()=>editableLayers.value.filter(layer=>!!selected.value[layer]));
const ready=computed(()=>canBind.value&&dirty.value&&!busy.value&&!loading.value&&chosenLayers.value.length>0&&chosenLayers.value.every(layer=>!!previews.value[layer]&&key(previews.value[layer]!)===selected.value[layer]));
function key(item:{id:string;version:number}){return item.id+'@'+item.version;}
function restore(){selected.value={dataset:currentLayer('dataset')?key({id:currentLayer('dataset')!.templateId,version:currentLayer('dataset')!.templateVersion}):'',sample:currentLayer('sample')?key({id:currentLayer('sample')!.templateId,version:currentLayer('sample')!.templateVersion}):''};baseline.value=JSON.stringify(selected.value);}
async function load(){const current=++generation;previewVersions.dataset++;previewVersions.sample++;loading.value=true;error.value='';previews.value={};try{const [value,items,project]=await Promise.all([request<ProjectSchemaState>(props.base+'/schema'+queryString({ref:props.branch})),request<Item[]>(props.base+'/schema/templates'),props.branch==='main'?Promise.resolve(undefined):request<ProjectSchemaState>(props.base+'/schema'+queryString({ref:'main'})).catch(()=>undefined)]);if(current!==generation)return;state.value=value;projectState.value=props.branch==='main'?value:project;templates.value=items;restore();for(const layer of layers)if(currentLayer(layer))previews.value[layer]=currentLayer(layer)!.snapshot;}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{if(current===generation)loading.value=false;}}
async function inspect(layer:SchemaLayer){const current=++previewVersions[layer],context=generation;error.value='';delete previews.value[layer];const item=templates.value.find(item=>item.targetKind===layer&&key(item)===selected.value[layer]);if(!item)return;try{const value=await request<PublishedTemplateSnapshot>(props.base+'/schema/templates/'+encodeURIComponent(item.id)+'/'+item.version);if(context===generation&&current===previewVersions[layer])previews.value[layer]=value;}catch(cause){if(context===generation&&current===previewVersions[layer])error.value=(cause as Error).message;}}
async function mayLeave(){if(busy.value){app.notify('规范采用正在提交，请等待结果。');return false;}if(!dirty.value)return true;const ok=await app.confirmAction('当前标签模板选择尚未提交，是否放弃此次选择？',{title:'未提交的采用草稿',confirmLabel:'放弃选择'});if(ok)restore();return ok;}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||busy.value){event.preventDefault();event.returnValue='';}}
const unregister=app.registerDraftGuard(mayLeave);onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath||mayLeave());window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>{generation++;previewVersions.dataset++;previewVersions.sample++;unregister();window.removeEventListener('beforeunload',beforeUnload);});
