async function bind(){if(!ready.value||!state.value)return;const current=generation,pinned=state.value.commitId,input:BindSchemaLayersInput={ref:props.branch,expectedCommit:pinned,layers:{}};for(const layer of chosenLayers.value){const snapshot=previews.value[layer]!;if(currentLayer(layer)?.checksum!==snapshot.checksum)input.layers[layer]={organizationId:snapshot.organizationId,templateId:snapshot.id,templateVersion:snapshot.version};}
  if(!input.layers.dataset&&!input.layers.sample)return;if(!await app.confirmAction('将明确提交当前所选的标签模板采用关系。样本规范升级需处理活动任务与复核影响。普通保存草稿不会执行此操作。',{title:'提交分支规范采用',confirmLabel:'采用并生成规范提交'}))return;if(current!==generation)return;
  busy.value=true;error.value='';try{const value=await post<ProjectSchemaState>(props.base+'/schema/layers',input);if(current!==generation)return;state.value=value;restore();app.notify('标签模板采用已提交');emit('bound');await load();}catch(cause){if(current===generation)error.value=(cause as Error).message;}finally{busy.value=false;}}
</script>
<template>
<section class="schema-binding"><header class="schema-binding-heading"><div><h3><Layers3 :size="19"/>标签模板</h3><p>项目标签模板统一在 main 维护；样本模板用于当前工作分支，均采用固定发布版本。</p></div><RouterLink v-if="canMaintain" to="/labels" class="btn"><Tag :size="14"/>标签管理</RouterLink></header>
<div v-if="loading" class="empty"><LoaderCircle class="spin" :size="23"/>读取两层规范…</div>
<template v-else-if="state"><div class="binding-version"><span>分支 {{branch}}</span><code>{{state.commitId}}</code></div><div class="binding-layers"><article v-for="layer in layers" :key="layer" class="binding-current"><CheckCircle2 :size="18"/><div><h4>{{layerName(layer)}}</h4><strong>{{currentLayer(layer)?currentLayer(layer)!.snapshot.name+' · v'+currentLayer(layer)!.templateVersion:'尚未采用独立发布版本'}}</strong><p v-if="currentLayer(layer)">固定校验 {{currentLayer(layer)!.checksum.slice(0,16)}}</p><p v-else>请采用该层的已发布模板后开始打标。</p></div></article></div>
<p v-if="!canBind" class="notice">当前身份可消费已采用规范；选择与升级需要独立的模板采用能力。</p>
<form v-if="canBind" @submit.prevent="bind"><label class="binding-domain">筛选领域<select v-model="domain"><option value="">全部领域</option><option v-for="value in domains" :key="value" :value="value">{{domainName(value)}}</option></select></label><div class="binding-selection"><section v-for="layer in layers" :key="layer"><label>{{layerName(layer)}}<select v-model="selected[layer]" :disabled="busy||(layer==='dataset'&&branch!=='main')" @change="inspect(layer)"><option value="" :disabled="!!currentLayer(layer)">选择已发布固定版本</option><option v-for="item in choices(layer)" :key="key(item)" :value="key(item)">{{item.name}} · v{{item.version}} · {{domainName(item.domain)}}</option></select></label><p v-if="layer==='dataset'&&branch!=='main'" class="notice">项目标签模板统一在 main 配置。<RouterLink :to="{query:{...route.query,branch:'main'}}">前往 main 设置</RouterLink></p><p v-if="!choices(layer).length" class="notice">该组织暂无此层的已发布模板，请由规范维护者另存并发布。</p><div v-if="previews[layer]" class="binding-preview"><h4>{{previews[layer]!.name}} · v{{previews[layer]!.version}}</h4><p>{{previews[layer]!.description}}</p><div><span v-for="column in previews[layer]!.columns" :key="column.id" :title="column.description">{{column.name}}<small v-if="previews[layer]!.bindings.find(item=>item.dimensionId===column.id)?.defaultVisible===false">扩展</small></span></div></div></section></div><p v-if="dirty" class="binding-draft">选择处于未提交草稿；不会因改变下拉选项而产生 Oxen commit。</p><p v-if="error" class="error-state" role="alert">{{error}}</p><footer><span>在 main 配置项目标签模板；样本模板可在各工作分支采用，升级仍需核对活动任务及复核。</span><button class="btn btn-primary" :disabled="!ready"><LoaderCircle v-if="busy" class="spin" :size="16"/>{{busy?'正在提交规范采用…':'采用并提交当前分支规范'}}</button></footer></form>
<div v-else class="binding-readonly"><section v-for="layer in layers" :key="layer"><h4>{{layerName(layer)}}</h4><div class="binding-preview"><span v-for="column in (layer==='dataset'?projectState:state)?.columnsByScope?.[layer==='dataset'?'dataset':'row']??[]" :key="column.id">{{column.name}}</span></div></section></div></template>
<p v-if="error&&!state" class="error-state" role="alert">{{error}}<button class="btn" @click="load">重试</button></p>
</section>
</template>
<style scoped>
